import { spawnSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { transformSync } from "esbuild";
import { appRuntimePaths } from "./runtime-manifest.mjs";
import { styleRuntimePaths } from "./style-manifest.mjs";
import { minifyCss } from "./lib/minify-css.mjs";

const root = dirname(dirname(fileURLToPath(import.meta.url)));

// Canonical tesseract.js worker patch. tesseract.js@7's worker file
// uses `require('..')` which trips Node's CJS resolver in certain
// pkg-packaged FS layouts; the fix is the explicit `../index.js`
// path. This patch lives here (build-time only) so the patched file
// is captured in the pkg snapshot. Do NOT add a runtime copy of this
// patch in the server; pkg's virtual FS is read-only at runtime,
// and the build-time patch already covers both dev and packaged
// flows because `npm start` runs build:app via prestart.
try {
  const workerFile = join(root, "node_modules", "tesseract.js", "src", "worker-script", "node", "index.js");
  const content = readFileSync(workerFile, "utf8");
  if (content.includes("require('..')")) {
    writeFileSync(workerFile, content.replace("require('..')", "require('../index.js')"), "utf8");
  }
} catch (err) {}
const cssBundlePath = "styles.bundle.css";

const banner = [
  "// Generated by scripts/build-app-bundle.mjs.",
  "// Keep source edits in app/ modules or app.js, then run npm run build:app.",
  "",
].join("\n");

function stripJsSourceMapComments(source) {
  return source.replace(/(?:^|\n)\/\/# sourceMappingURL=.*(?:\n|$)/g, "\n").trimEnd();
}

function compactJsLeadingWhitespace(source) {
  let output = "";
  let quote = "";
  let escaped = false;
  let lineStart = true;
  let pendingBlankLine = false;
  let inRegex = false;

  for (let index = 0; index < source.length; index += 1) {
    const char = source[index];
    const next = source[index + 1];

    if (quote) {
      output += char;
      if (escaped) {
        escaped = false;
      } else if (char === "\\") {
        escaped = true;
      } else if (char === quote) {
        quote = "";
      }
      lineStart = char === "\n";
      continue;
    }

    if (inRegex) {
      output += char;
      if (escaped) {
        escaped = false;
      } else if (char === "\\") {
        escaped = true;
      } else if (char === "/") {
        inRegex = false;
      }
      lineStart = char === "\n";
      continue;
    }

    if (char === "\"" || char === "'" || char === "`") {
      if (pendingBlankLine && output && !output.endsWith("\n")) output += "\n";
      pendingBlankLine = false;
      quote = char;
      output += char;
      lineStart = false;
      continue;
    }

    if (char === "/" && next === "/") {
      if (source.startsWith("// =====", index)) {
        let lineEnd = index;
        while (lineEnd < source.length && source[lineEnd] !== "\n") {
          lineEnd += 1;
        }
        output += source.slice(index, lineEnd);
        index = lineEnd - 1;
        lineStart = false;
        continue;
      }
      index += 1;
      while (index < source.length && source[index] !== "\n") {
        index += 1;
      }
      index -= 1;
      continue;
    }

    if (char === "/" && next === "*") {
      index += 2;
      while (index < source.length && !(source[index] === "*" && source[index + 1] === "/")) {
        index += 1;
      }
      index += 1;
      continue;
    }

    if (char === "/") {
      const prevText = output.trimEnd();
      const lastChar = prevText.at(-1);
      const isRegexStart = !lastChar || "=,;:?&|!([{~^+-*/%<>".includes(lastChar) || 
        /\b(return|yield|delete|typeof|void|throw|await|typeof|instanceof|in|do|else|case)$/.test(prevText);
      if (isRegexStart) {
        inRegex = true;
        output += char;
        lineStart = false;
        continue;
      }
    }

    if (char === "\n") {
      if (!lineStart) output += "\n";
      else pendingBlankLine = true;
      lineStart = true;
      continue;
    }

    if (lineStart && (char === " " || char === "\t")) continue;

    if (pendingBlankLine && output && !output.endsWith("\n")) output += "\n";
    pendingBlankLine = false;
    output += char;
    lineStart = false;
  }

  return output.trimEnd();
}

const body = appRuntimePaths
  .map((path) => [
    `// ===== ${path} =====`,
    stripJsSourceMapComments(readFileSync(join(root, path), "utf8")),
    "",
  ].join("\n"))
  .join("\n");

const appBundlePath = join(root, "app.bundle.js");
const minifiedBody = transformSync(compactJsLeadingWhitespace(body), {
  charset: "utf8",
  legalComments: "none",
  loader: "js",
  minifyIdentifiers: false,
  minifySyntax: false,
  minifyWhitespace: true,
  target: "esnext",
}).code.trim();
const sourceSectionManifest = appRuntimePaths
  .map((path) => `// Source section: ${path}`)
  .join("\n");
writeFileSync(appBundlePath, `${banner}${sourceSectionManifest}\n${minifiedBody}\n`, "utf8");

const syntaxCheck = spawnSync(process.execPath, ["--check", appBundlePath], {
  cwd: root,
  encoding: "utf8",
});
if (syntaxCheck.status !== 0) {
  console.error(syntaxCheck.stderr || syntaxCheck.stdout);
  process.exit(syntaxCheck.status || 1);
}

console.log(`Built app.bundle.js from ${appRuntimePaths.length} source files.`);

const cssSource = styleRuntimePaths
  .map((path) => readFileSync(join(root, path), "utf8"))
  .join("\n");
const cssBundle = minifyCss(cssSource);
writeFileSync(join(root, cssBundlePath), `${cssBundle}\n`, "utf8");
console.log(`Built ${cssBundlePath} from ${styleRuntimePaths.length} source files.`);
